CREATE TEMPORARY VIEW dws_smart_ui_1d_${grass_region_without_quote} AS
SELECT
    user_id
    ,item_id
    ,image_id
    ,xui_item_status
    ,xui_image_stage
    ,is_ads
    ,image_aspect_ratio
    ,target_type

    ,SUM(CASE WHEN local_date = ${local_date}  THEN imp_cnt ELSE NULL END) AS imp_cnt_1d
    ,SUM(CASE WHEN local_date = ${local_date}  THEN click_cnt ELSE NULL END) AS click_cnt_1d
    ,SUM(CASE WHEN local_date = ${local_date}  THEN order_cnt ELSE NULL END) AS order_cnt_1d
    ,SUM(CASE WHEN local_date = ${local_date}  THEN gmv ELSE NULL END) AS gmv_1d

    ,SUM(imp_cnt) AS imp_cnt_30d
    ,SUM(click_cnt) AS click_cnt_30d
    ,SUM(order_cnt) AS order_cnt_30d
    ,SUM(gmv) AS gmv_30d
FROM
    srdi_mart.dws_sr_data_warehouse_search_smart_ui_metrics_1d
WHERE
    local_date BETWEEN date_sub(${local_date}, 29) AND ${local_date}
    AND grass_region = ${grass_region}
    AND user_id > 0
GROUP BY 
    1,2,3,4,5,6,7,8;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_1d_data_${grass_region_without_quote} AS
SELECT  
    item_id 
FROM 
    srdi_mart.dws_sr_data_warehouse_search_smart_ui_metrics_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND imp_cnt > 0
    AND user_id > 0
GROUP BY
    item_id;

--sql_divide_splitter--
CREATE TEMPORARY VIEW dws_image_item_nd_${grass_region_without_quote} AS
SELECT
    item_id
    ,image_id
    ,CAST(imp_cnt AS DOUBLE) AS imp_cnt
    ,CAST(clk_cnt AS DOUBLE) AS clk_cnt
FROM 
    search_algo.search_personalized_ui_metrics_month
WHERE 
    month >= '202304'
    AND month <= DATE_FORMAT(ADD_MONTHS(${local_date}, -1),'yyyyMM')
    AND grass_region = ${grass_region}
UNION ALL
SELECT
    item_id
    ,image_id
    ,CAST(imp_cnt AS DOUBLE) AS imp_cnt
    ,CAST(clk_cnt AS DOUBLE) AS clk_cnt
FROM 
    search_algo.search_personalized_ui_metrics_di
WHERE 
    DATE_FORMAT(grass_date,'yyyyMM') > DATE_FORMAT(ADD_MONTHS(${local_date}, -1),'yyyyMM')
    AND grass_date <= ${local_date}
    AND grass_region = ${grass_region};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_restrict_item_nd_${grass_region_without_quote} AS
SELECT
    item_id
    ,image_id
    ,SUM(imp_cnt) AS algo_imp_cnt_nd
    ,SUM(clk_cnt) AS algo_click_cnt_nd
    ,RANK() OVER (PARTITION BY item_id ORDER BY CASE
        WHEN SUM(imp_cnt) >= 100 AND SUM(clk_cnt) > 0 THEN SUM(clk_cnt) / SUM(imp_cnt)
        ELSE NULL
    END DESC NULLS LAST
    ) AS item_ctr_rank
FROM 
    dws_image_item_nd_${grass_region_without_quote} 
WHERE
    item_id IN (select item_id from dws_1d_data_${grass_region_without_quote})
GROUP BY 
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW cover_image_${grass_region_without_quote} AS
SELECT
    item_id
    ,split(images,',')[0] AS image_id
FROM
    srdi_mart.dim_sr_data_warehouse_item
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
GROUP BY 1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW aigc_image_${grass_region_without_quote} AS
SELECT
    img_id AS image_id
FROM 
    szci_mmu.smart_ui_search_creative_placement_tab__reg_daily_s0_live
WHERE
    grass_date = ${local_date}
    AND library_name IN (
        'aigc_bg'
        ,'aigc_bg_sticker'
        ,'aigc_bg_combination'
        ,'sellerimage_sticker'
        ,'try_on'
        ,'try_on_sticker'
        ,'try_on_combination'
        ,'generation_control'
        ,'generation_treatment'
    )
GROUP BY image_id;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_smart_ui_metrics_30d
PARTITION (
    grass_region = ${grass_region},
    local_date = ${local_date}
)
SELECT
    user_id
    ,a.item_id
    ,a.image_id
    ,IF(b.image_id IS NOT NULL, TRUE, FALSE) AS is_cover_image
    ,IF(c.image_id IS NOT NULL, TRUE, FALSE) AS is_aigc_image
    ,xui_item_status
    ,is_ads

    ,imp_cnt_1d
    ,click_cnt_1d
    ,order_cnt_1d
    ,gmv_1d

    ,imp_cnt_30d
    ,click_cnt_30d
    ,order_cnt_30d 
    ,gmv_30d

    ,algo_imp_cnt_nd
    ,algo_click_cnt_nd

    ,xui_image_stage
    ,CASE WHEN item_ctr_rank = 1 AND algo_imp_cnt_nd >= 100 AND algo_click_cnt_nd > 0 THEN true ELSE false END AS is_best_ctr

    ,image_aspect_ratio
    ,target_type
FROM
    dws_smart_ui_1d_${grass_region_without_quote} a
    LEFT JOIN dws_restrict_item_nd_${grass_region_without_quote} d 
        ON a.item_id = d.item_id 
        AND a.image_id = d.image_id 
    LEFT JOIN cover_image_${grass_region_without_quote} b
        ON a.item_id = b.item_id 
        AND a.image_id = b.image_id
    LEFT JOIN aigc_image_${grass_region_without_quote} c
        ON a.image_id = c.image_id;
